// TypeScript Version: 4.1

/**
* Evaluates a polynomial using Horner's rule.
*
* The polynomial is defined by the coefficients `coef` such that
*
*     p(x) = coef[0] + coef[1]·x + ... + coef[N]·x^N
*
* For best performance, coefficients should be provided as a
* `Float64Array`.
*
* @param x - input value
* @param coef - polynomial coefficients in ascending order of degree
* @param N - degree of the polynomial
* @returns polynomial value
*
* @example
* var coef = [ 1.0, 2.0, 3.0 ];
* var y = polevl( 2.0, coef, 2 );
* // returns 17.0
*
* @example
* var coef = new Float64Array( [ 1.0, 2.0, 3.0 ] );
* var y = polevl( 0.5, coef, 2 );
* // returns 2.75
*
* @example
* var y = polevl( NaN, coef, 2 );
* // returns NaN
*/
declare function polevl(
	x: number,
	coef: ArrayLike<number>,
	N: number
): number;


// EXPORTS //

export = polevl;
